#!/usr/bin/env python3
"""Generate public English/German documentation from one maintained content source."""
from pathlib import Path
import json,re
r=Path(__file__).resolve().parents[1];c=json.loads((r/'docs/content.json').read_text());version=c['version'];base='https://github.com/deckerweb/portfolio-content';wiki=base+'/wiki/'
def anchor(s):return re.sub(r'[^\w\s-]','',s.lower()).replace(' ','-')
def plain(s):
 s=re.sub(r'!\[[^\]]*\]\([^)]*\)\n?','',s);s=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',r'\1 (\2)',s);return s.replace('**','').replace('`','')
for code,d in c['languages'].items():
 de=code=='de';lang='Deutsch' if de else 'English';other='English' if de else 'Deutsch';suffix='-de' if de else ''
 titles=['Auf einen Blick','Installation und erste Schritte','Projektvorlage','Updates und Library','Multisite und Datenhaltung','Datenschutz und Verbindungen','Bestehende Integrationen','FAQ','Änderungsprotokoll','Über das Projekt','Support und Sicherheit','Lizenz und Herkunft'] if de else ['At a glance','Installation and first steps','Project starter','Updates and Library','Multisite and data','Privacy and connections','Existing integrations','FAQ','Changelog','About the project','Support and security','License and provenance']
 faq='\n\n'.join('**'+q+'** '+a for q,a in d['faq'])+f'\n\n[{"Fragen nach Themen" if de else "FAQ by topic"}]({wiki}FAQ-{lang})'
 about='David Decker – DECKERWEB entwickelt Portfolio Content seit 2019. Das Plugin trennt Projektinhalte von der Darstellung durch Theme oder Builder. GitHub ist der Veröffentlichungsweg; ClassicPress wird nicht offiziell unterstützt.' if de else 'David Decker – DECKERWEB has maintained Portfolio Content since 2019. The plugin keeps project content independent of theme or builder presentation. Releases are distributed through GitHub; ClassicPress is not officially supported.'
 support=f'[{"Fehler und Fragen" if de else "Bugs and questions"}]({base}/issues) · [Discussions]({base}/discussions)\n\n'+('Sicherheitslücken bitte vertraulich melden: ' if de else 'Report vulnerabilities privately: ')+f'[Security reporting]({base}/security/advisories/new). '+('Keine Zugangsdaten oder vertraulichen Kundeninhalte senden. Hinweise: [Sicherheit](SECURITY-de.md).' if de else 'Do not send credentials or private customer content. See [security policy](SECURITY.md).')+'\n\n[Ko-fi](https://ko-fi.com/deckerweb) · [Buy Me a Coffee](https://buymeacoffee.com/daveshine) · [PayPal](https://paypal.me/deckerweb)'
 license=('© 2019–2026 David Decker – DECKERWEB · [GPL v2 oder neuer](LICENSE).\n\nEnthält deckerweb Library 1.1.0 und deckerweb Updater 2.2.0 von David Decker, jeweils GPL-2.0-or-later. Admin-Stile und Dialogverhalten wurden aus Brand Admin Schemes von David Decker übernommen und angepasst, GPL-2.0-or-later. Grafiken: freigegebenes Portfolio-Content-Design A von DECKERWEB; SVG-Quelldateien und PNG-Exporte werden mit GPL-2.0-or-later bereitgestellt. Systemschriften werden referenziert; Schriftdateien werden nicht mitgeliefert.' if de else '© 2019–2026 David Decker – DECKERWEB · [GPL v2 or later](LICENSE).\n\nIncludes deckerweb Library 1.1.0 and deckerweb Updater 2.2.0 by David Decker, both GPL-2.0-or-later. Administration styles and dialog behavior are adapted from Brand Admin Schemes by David Decker, GPL-2.0-or-later. Artwork: approved Portfolio Content Design A by DECKERWEB; SVG sources and PNG exports are provided under GPL-2.0-or-later. System fonts are referenced; no font files are bundled.')+('\n\nGitHub Pages nutzt das Cayman-Theme (CC0-1.0); die lokale Vorlage verwendet Systemschriften.' if de else '\n\nGitHub Pages uses the Cayman theme (CC0-1.0); the local layout uses system fonts.')+f'\n\n[Library](https://github.com/deckerweb/deckerweb-plugin-library) · [Updater](https://github.com/deckerweb/deckerweb-updater) · [Brand Admin Schemes](https://github.com/deckerweb/brand-admin-schemes) · [Cayman](https://github.com/pages-themes/cayman)'
 bodies=[d['features'],d['installation'],d['starter'],d['updates'],d['data'],d['traffic'],d['compatibility'],faq,d['changelog'].split('\n\n',1)[1].replace('## ','### '),about,support,license]
 head='# Portfolio Content\n\n'+f'![Portfolio Content](assets-github/banner-{"de-" if de else ""}1280x640.png)\n\n**{d["tagline"]}** {d["about"]}\n\n**Version:** {version} · **{"Voraussetzungen" if de else "Requires"}:** WordPress 6.7+ / PHP 8.1+ · **{"Lizenz" if de else "License"}:** GPL v2 '+('oder neuer' if de else 'or later')+f'\n\n[Download]({base}/releases/latest) · [{"Anleitung" if de else "User guide"}]({wiki}{lang}) · [{other}](README'+('' if de else '-de')+'.md)\n\n'
 toc='## '+('Inhalt' if de else 'Contents')+'\n\n'+'\n'.join(f'- [{t}](#{anchor(t)})' for t in titles)+'\n\n'
 screens='## '+('Screenshots' if de else 'Screenshots')+'\n\n'+'\n\n'.join('### '+title+'\n\n!['+title+'](assets/screenshots/'+name+'-'+code+'.jpg)' for title,name in zip(['Einrichtungscheck','Projektliste und Filter','Projektvorlage im klassischen Editor'] if de else ['Setup check','Project list and filters','Project template in the classic editor'],['setup','projects','template']))+'\n\n'
 readme=head+toc+'\n\n'.join('## '+t+'\n\n'+b for t,b in zip(titles,bodies))+'\n';readme=readme.replace('## '+titles[8]+'\n',screens+'## '+titles[8]+'\n',1);(r/('README'+suffix+'.md')).write_text(readme)
 headers=f'=== Portfolio Content ===\nContributors: deckerweb\nTags: portfolio, projects, custom post type, block patterns\nRequires at least: 6.7\nRequires PHP: 8.1\nTested up to: 7.1.3\nStable tag: {version}\nLicense: GPL-2.0-or-later\nLicense URI: https://www.gnu.org/licenses/gpl-2.0.html\n\n'+d['tagline']+'\n\n'
 desc='\n\n'.join([d['about'],d['features'],d['starter'],d['updates'],d['data'],d['traffic'],support,license]);txt=headers+'== Description ==\n\n'+plain(desc)+'\n\n== Installation ==\n\n'+plain(d['installation'])+'\n\n== Frequently Asked Questions ==\n\n'+'\n\n'.join('= '+q+' =\n\n'+a for q,a in d['faq'])+f'\n\n{ "Fragen nach Themen" if de else "FAQ by topic" }: {wiki}FAQ-{lang}\n\n== Changelog ==\n\n'+re.sub(r'^## (.+)$',r'= \1 =',plain(d['changelog']).split('\n\n',1)[1],flags=re.M);(r/('readme'+suffix+'.txt')).write_text(txt)
 (r/('CHANGELOG'+suffix+'.md')).write_text(d['changelog']);(r/'docs'/('changelog'+suffix+'.txt')).write_text(d['changelog'])
 doc='\n\n'.join('## '+t+'\n\n'+plain(b) for t,b in zip(titles[:8],bodies[:8]))+'\n';(r/'docs'/('documentation'+suffix+'.txt')).write_text(doc)
 w=r/'docs/wiki';w.mkdir(exist_ok=True);wd=readme.replace('(assets/screenshots/',f'({base}/raw/master/assets/screenshots/').replace('(assets-github/',f'({base}/raw/master/assets-github/').replace('(README-de.md)',f'({wiki}Deutsch)').replace('(README.md)',f'({wiki}English)').replace('(SECURITY-de.md)',f'({base}/blob/master/SECURITY-de.md)').replace('(SECURITY.md)',f'({base}/blob/master/SECURITY.md)').replace('(LICENSE)',f'({base}/blob/master/LICENSE)');wd+='\n## '+('Leere Suchergebnisse' if de else 'Empty search results')+'\n\n!['+('Filter zurücksetzen' if de else 'Reset filters')+']('+base+'/raw/master/assets/screenshots/empty-'+code+'.jpg)\n';(w/(lang+'.md')).write_text(wd)
 fq='# '+('Fragen nach Themen' if de else 'FAQ by topic')+f'\n\n[{other}]({wiki}FAQ-{other}) · [{"Anleitung" if de else "User guide"}]({wiki}{lang})\n\n## '+('Einstieg und Alltag' if de else 'Getting started and daily use')+'\n\n'+'\n\n'.join('### '+q+'\n\n'+a for q,a in d['faq'])+'\n\n'+'\n\n'.join('## '+t+'\n\n'+'\n\n'.join('### '+q+'\n\n'+a for q,a in entries) for t,entries in d['faq_topics'])+'\n';(w/f'FAQ-{lang}.md').write_text(fq)
 (w/f'Changelog-{lang}.md').write_text(d['changelog']+f'\n[{other}]({wiki}Changelog-{other})\n')
 security=('# Sicherheit\n\nBitte melde Sicherheitslücken vertraulich über [GitHub Private Vulnerability Reporting]('+base+'/security/advisories/new). Der Meldeweg gilt auch für die eingebettete Library und den Updater. Nenne Plugin- und Komponentenversion, WordPress-/PHP-Version, nachvollziehbare Schritte und mögliche Auswirkungen. Sende keine Passwörter, Tokens oder privaten Kundendaten. Sicherheitsdetails bitte nicht zuerst in öffentlichen Issues oder Discussions veröffentlichen. Nach Prüfung werden Fix und Offenlegung abgestimmt; es werden keine festen Reaktionsfristen zugesagt.\n\nDer jeweils aktuelle stabile Release ist die Grundlage für Sicherheitsfixes. Für normale Fehler oder Fragen stehen Issues und Discussions zur Verfügung.\n\n[English](SECURITY.md)\n' if de else '# Security\n\nReport vulnerabilities privately through [GitHub Private Vulnerability Reporting]('+base+'/security/advisories/new). This route also covers the embedded Library and updater. Include plugin/component versions, WordPress/PHP versions, reproduction steps and potential impact. Do not send passwords, tokens or private customer data. Do not disclose security details first in public issues or discussions. Fixes and disclosure are coordinated after assessment; no fixed response deadlines are promised.\n\nThe latest stable release is the baseline for security fixes. Use issues and discussions for ordinary bugs and questions.\n\n[Deutsch](SECURITY-de.md)\n');(r/('SECURITY'+suffix+'.md')).write_text(security)
(w/'Home.md').write_text(f'# Portfolio Content\n\n![Portfolio Content]({base}/raw/master/assets-github/banner-1280x640.png)\n\n**Your projects. Ready to share. / Deine Projekte. Bereit zum Teilen.**\n\nProjects, categories, tags, editable starter content and native block patterns. Your theme or builder controls the presentation.\n\nProjekte, Kategorien, Schlagwörter, bearbeitbare Projektvorlage und native Block-Vorlagen. Die Darstellung bestimmt dein Theme oder Builder.\n\n## English\n\n- [User guide](English): installation, projects, settings, updates, Multisite and data.\n- [FAQ by topic](FAQ-English): everyday questions and technical guidance.\n- [Complete changelog](Changelog-English).\n\n## Deutsch\n\n- [Anleitung](Deutsch): Installation, Projekte, Einstellungen, Updates, Multisite und Daten.\n- [Fragen nach Themen](FAQ-Deutsch): Alltag und technische Hinweise.\n- [Vollständiger Änderungsverlauf](Changelog-Deutsch).\n\n[Download]({base}/releases/latest) · [Issues]({base}/issues) · [Security]({base}/security/advisories/new)\n')
(w/'_Sidebar.md').write_text('## English\n- [User guide](English)\n- [FAQ by topic](FAQ-English)\n- [Changelog](Changelog-English)\n\n## Deutsch\n- [Anleitung](Deutsch)\n- [Fragen nach Themen](FAQ-Deutsch)\n- [Änderungsverlauf](Changelog-Deutsch)\n')
# Compact bilingual navigation uses formatted Wiki page URLs.
(w/'_Sidebar.md').write_text('## English\n\n- [User guide]('+wiki+'English)\n- [FAQ by topic]('+wiki+'FAQ-English)\n- [Changelog]('+wiki+'Changelog-English)\n- [Help and security]('+base+'/blob/master/SECURITY.md)\n\n## Deutsch\n\n- [Anleitung]('+wiki+'Deutsch)\n- [Fragen nach Themen]('+wiki+'FAQ-Deutsch)\n- [Änderungsverlauf]('+wiki+'Changelog-Deutsch)\n- [Hilfe und Sicherheit]('+base+'/blob/master/SECURITY-de.md)\n')
(w/'_Footer.md').write_text('**Portfolio Content · Documentation / Dokumentation**\n\n[Wiki home / Wiki-Startseite]('+wiki+'Home) · [Repository]('+base+') · [Downloads & Releases]('+base+'/releases)\n\n[Help & bugs / Hilfe & Fehler]('+base+'/issues) · [Discussions / Austausch]('+base+'/discussions) · [Security / Sicherheit]('+base+'/blob/master/SECURITY.md)\n\n© 2019–2026 David Decker – DECKERWEB.  \nPlugin: [GPL v2 or later / GPL v2 oder höher](https://www.gnu.org/licenses/gpl-2.0.html).\n')
# Independent language pages keep section anchors and navigation unambiguous.
for code,name in [('en','README.md'),('de','README-de.md')]:
 page=(r/name).read_text().replace('(README-de.md)','(de.html)').replace('(README.md)','(en.html)').replace('(SECURITY-de.md)',f'({base}/blob/master/SECURITY-de.md)').replace('(SECURITY.md)',f'({base}/blob/master/SECURITY.md)').replace('(LICENSE)',f'({base}/blob/master/LICENSE)')
 (r/(code+'.md')).write_text('---\nlayout: default\ntitle: Portfolio Content\nlang: '+('de-DE' if code=='de' else 'en-US')+'\n---\n\n'+page)
(r/'index.md').write_text('---\nlayout: default\ntitle: Portfolio Content\n---\n\n![Portfolio Content](assets-github/banner-1280x640.png)\n\n## English\n\n'+c['languages']['en']['about']+'\n\n[User guide](en.html) · [FAQ by topic]('+wiki+'FAQ-English)\n\n## Deutsch\n\n'+c['languages']['de']['about']+'\n\n[Anleitung](de.html) · [Fragen nach Themen]('+wiki+'FAQ-Deutsch)\n\n[Download]('+base+'/releases/latest) · [GitHub]('+base+')\n')
layouts=r/'_layouts';layouts.mkdir(exist_ok=True)
(layouts/'default.html').write_text("""<!doctype html>
<html lang="{{ page.lang | default: 'en-US' }}">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ page.title | escape }}</title><link rel="stylesheet" href="{{ '/assets/css/style.css' | relative_url }}"></head>
<body><a href="#content" class="skip-link">Skip to content / Zum Inhalt</a>
<header class="page-header"><h1 class="project-name">Portfolio Content</h1><p class="project-tagline">Your projects. Ready to share. / Deine Projekte. Bereit zum Teilen.</p><nav aria-label="Language / Sprache"><a class="btn" href="{{ '/en.html' | relative_url }}">English</a><a class="btn" href="{{ '/de.html' | relative_url }}">Deutsch</a><a class="btn" href="https://github.com/deckerweb/portfolio-content">GitHub</a></nav></header>
<main id="content" class="main-content">{{ content }}<footer class="site-footer">© 2019–2026 David Decker – DECKERWEB · <a href="https://github.com/deckerweb/portfolio-content/blob/master/LICENSE">GPL v2 or later</a></footer></main></body></html>
""")
(r/'_config.yml').write_text('theme: jekyll-theme-cayman\ntitle: Portfolio Content\ndescription: Your projects. Ready to share. / Deine Projekte. Bereit zum Teilen.\nshow_downloads: false\nexclude: [includes, languages, tests, tools, docs, assets-design, composer.json, README.md, README-de.md, readme.txt, readme-de.txt, SECURITY.md, SECURITY-de.md, CHANGELOG.md, CHANGELOG-de.md, LICENSE, portfolio-content.php, index.php, uninstall.php]\n')
(r/'assets/css/style.scss').write_text('---\n---\n\n@import "{{ site.theme }}";\n.page-header {background-color:#6430c7;background-image:linear-gradient(120deg,#3023AE,#6430c7);}\n.main-content h1,.main-content h2,.main-content h3,.main-content h4,.main-content h5,.main-content h6{font-weight:700;color:#5524a3;}\n.main-content a{color:#5524a3;}\nbody{font-family:system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;}\n.skip-link{position:absolute;left:-10000px;top:0;padding:12px;background:#fff;color:#5524a3;z-index:10}.skip-link:focus{left:12px}\n')
(r/'.github/FUNDING.yml').write_text('ko_fi: deckerweb\nbuy_me_a_coffee: daveshine\ncustom: https://paypal.me/deckerweb\n')
print('Generated four readmes, FAQ, changelogs, local documents, security, Wiki and Pages')
